INSERT INTO `thong_bao` (`ma_thong_bao`, `tieu_de`, `noi_dung`, `nhom_rui_ro`, `ma_lop`, `ma_sv`, `ngay_gui`, `nguoi_gui`, `so_luong_nhan`, `trang_thai`) VALUES ('TB-EAUT-01', '[EAUT] THÔNG BÁO XÉT HỌC BỔNG KHUYẾN KHÍCH HỌC TẬP K14', 'Chúc mừng các sinh viên đạt GPA >= 3.2 trong học kỳ 2 năm học 2023-2024. Đề nghị sinh viên nộp hồ sơ xét học bổng tại VP Đoàn trường trước ngày 20/09/2026.', 'TIER_1', 'ALL', NULL, CURRENT_TIMESTAMP, 'Phòng Đào Tạo EAUT', 24, 'DA_GUI');
INSERT INTO `thong_bao` (`ma_thong_bao`, `tieu_de`, `noi_dung`, `nhom_rui_ro`, `ma_lop`, `ma_sv`, `ngay_gui`, `nguoi_gui`, `so_luong_nhan`, `trang_thai`) VALUES ('TB-EAUT-02', '[EAUT] KẾ HOẠCH ĐĂNG KÝ HỌC PHẦN HỌC KỲ 1 NĂM HỌC 2024-2025', 'Hệ thống cổng đào tạo eaut.edu.vn mở cổng đăng ký tín chỉ từ 8h00 ngày 25/08/2026. Sinh viên chú ý các môn tiên quyết.', 'TIER_2', 'ALL', NULL, CURRENT_TIMESTAMP, 'Phòng Đào Tạo EAUT', 60, 'DA_GUI');
INSERT INTO `thong_bao` (`ma_thong_bao`, `tieu_de`, `noi_dung`, `nhom_rui_ro`, `ma_lop`, `ma_sv`, `ngay_gui`, `nguoi_gui`, `so_luong_nhan`, `trang_thai`) VALUES ('TB-EAUT-03', '[EAUT] YÊU CẦU TƯ VẤN HỌC VỤ BẮT BUỘC ĐỐI VỚI SINH VIÊN BỊ CẢNH BÁO', 'Các sinh viên có tên trong danh sách cảnh báo Mức 1, Mức 2 và Buộc thôi học phải liên hệ ngay Cố vấn học tập trước ngày 15/08/2026.', 'TIER_3', 'ALL', NULL, CURRENT_TIMESTAMP, 'Ban CVHT EAUT', 36, 'DA_GUI');
INSERT INTO `thong_bao` (`ma_thong_bao`, `tieu_de`, `noi_dung`, `nhom_rui_ro`, `ma_lop`, `ma_sv`, `ngay_gui`, `nguoi_gui`, `so_luong_nhan`, `trang_thai`) VALUES ('TB-EAUT-04', '[KHOA CNTT] HỘI THẢO CÔNG NGHỆ & ĐỊNH HƯỚNG NGHỀ NGHIỆP AI & CLOUD', 'Khoa CNTT phối hợp cùng doanh nghiệp đối tác tổ chức workshop chia sẻ công nghệ vào 9h00 sáng thứ Bảy tại Hội trường A.', 'ALL', 'DCCTPM14A', NULL, CURRENT_TIMESTAMP, 'TS. Đinh Văn Phong', 15, 'DA_GUI');
INSERT INTO `thong_bao` (`ma_thong_bao`, `tieu_de`, `noi_dung`, `nhom_rui_ro`, `ma_lop`, `ma_sv`, `ngay_gui`, `nguoi_gui`, `so_luong_nhan`, `trang_thai`) VALUES ('TB-EAUT-05', '[KHOA Ô TÔ] LỊCH THỰC TẬP TỐT NGHIỆP VÀ AN TOÀN XƯỞNG THỰC HÀNH', 'Yêu cầu 100% sinh viên lớp DCOTO14A trang bị đồ bảo hộ lao động đầy đủ trước khi vào xưởng Ô tô.', 'ALL', 'DCOTO14A', NULL, CURRENT_TIMESTAMP, 'PGS.TS. Nguyễn Thanh Hải', 15, 'DA_GUI');
INSERT INTO `thong_bao` (`ma_thong_bao`, `tieu_de`, `noi_dung`, `nhom_rui_ro`, `ma_lop`, `ma_sv`, `ngay_gui`, `nguoi_gui`, `so_luong_nhan`, `trang_thai`) VALUES ('TB-CHAT-01', 'Chúc mừng kết quả học tập xuất sắc ngành Công nghệ thông tin', 'Thầy chúc mừng em Nam đã đạt GPA 3.65 đứng đầu lớp DCCTPM14A kỳ vừa qua. Tiếp tục giữ vững phong độ nhé em!', 'CA_NHAN', 'DCCTPM14A', '20230001', CURRENT_TIMESTAMP, 'TS. Đinh Văn Phong', 1, 'DA_GUI');
INSERT INTO `thong_bao` (`ma_thong_bao`, `tieu_de`, `noi_dung`, `nhom_rui_ro`, `ma_lop`, `ma_sv`, `ngay_gui`, `nguoi_gui`, `so_luong_nhan`, `trang_thai`) VALUES ('TB-CHAT-02', '📬 [SV PHẢN HỒI] Em cảm ơn thầy và muốn hỏi về học bổng', 'Dạ em chào thầy Phong, em cảm ơn thầy ạ! Cho em hỏi hồ sơ xét học bổng kỳ này cần nộp bản sao bảng điểm có xác nhận không ạ?', 'PHAN_HOI_SV', 'ALL', '20230001', CURRENT_TIMESTAMP, 'Vũ Đình Anh (20230001)', 1, 'DA_DOC');
INSERT INTO `thong_bao` (`ma_thong_bao`, `tieu_de`, `noi_dung`, `nhom_rui_ro`, `ma_lop`, `ma_sv`, `ngay_gui`, `nguoi_gui`, `so_luong_nhan`, `trang_thai`) VALUES ('TB-CHAT-03', '💬 [CVHT TRẢ LỜI] Hướng dẫn thủ tục học bổng', 'Chào em, bản điểm thầy sẽ trực tiếp ký xác nhận và gửi VP Đoàn cho em nhé. Em chỉ cần nộp đơn xin xét theo mẫu thôi.', 'CVHT_TRA_LOI', 'CA_NHAN', '20230001', CURRENT_TIMESTAMP, 'TS. Đinh Văn Phong', 1, 'DA_DOC');
INSERT INTO `thong_bao` (`ma_thong_bao`, `tieu_de`, `noi_dung`, `nhom_rui_ro`, `ma_lop`, `ma_sv`, `ngay_gui`, `nguoi_gui`, `so_luong_nhan`, `trang_thai`) VALUES ('TB-CHAT-04', 'Lịch hẹn gặp mặt tư vấn học tập và kế hoạch học lại', 'Chào em Duy, học kỳ vừa qua em bị cảnh báo Mức 1. Chiều thứ Ba tuần tới 14h00 em đến văn phòng Khoa gặp thầy để trao đổi kế hoạch học lại nhé.', 'CA_NHAN', 'DCCTPM14A', '20230022', CURRENT_TIMESTAMP, 'TS. Đinh Văn Phong', 1, 'DA_GUI');
INSERT INTO `thong_bao` (`ma_thong_bao`, `tieu_de`, `noi_dung`, `nhom_rui_ro`, `ma_lop`, `ma_sv`, `ngay_gui`, `nguoi_gui`, `so_luong_nhan`, `trang_thai`) VALUES ('TB-CHAT-05', '📬 [SV PHẢN HỒI] Em xác nhận lịch hẹn tư vấn', 'Dạ em chào thầy, thứ Ba tuần tới 14h00 em sẽ có mặt đúng giờ tại VP Khoa ạ. Em cảm ơn thầy đã nhắc nhở em!', 'PHAN_HOI_SV', 'ALL', '20230022', CURRENT_TIMESTAMP, 'Bùi Hoàng Duy (20230022)', 1, 'SV_CHUA_DOC');
INSERT INTO `thong_bao` (`ma_thong_bao`, `tieu_de`, `noi_dung`, `nhom_rui_ro`, `ma_lop`, `ma_sv`, `ngay_gui`, `nguoi_gui`, `so_luong_nhan`, `trang_thai`) VALUES ('TB-CHAT-06', 'Cảnh báo học vụ Mức 2 và yêu cầu cam kết tiến độ', 'Chào em Nam, em đang bị cảnh báo Mức 2 và nợ 8 tín chỉ. Em cần nộp bản cam kết cải thiện GPA trước ngày 15/09.', 'CA_NHAN', 'DCCNTT14B', '20230026', CURRENT_TIMESTAMP, 'TS. Đinh Văn Phong', 1, 'DA_GUI');
INSERT INTO `thong_bao` (`ma_thong_bao`, `tieu_de`, `noi_dung`, `nhom_rui_ro`, `ma_lop`, `ma_sv`, `ngay_gui`, `nguoi_gui`, `so_luong_nhan`, `trang_thai`) VALUES ('TB-CHAT-07', '📬 [SV PHẢN HỒI] Em xin tư vấn môn học lại để gỡ cảnh báo', 'Thưa thầy, kỳ này em đã đăng ký học lại 2 môn Toán rời rạc và Cấu trúc dữ liệu. Thầy cho em xin lời khuyên để phân bổ thời gian hợp lý ạ.', 'PHAN_HOI_SV', 'ALL', '20230026', CURRENT_TIMESTAMP, 'Phan Gia Nam (20230026)', 1, 'SV_CHUA_DOC');
INSERT INTO `thong_bao` (`ma_thong_bao`, `tieu_de`, `noi_dung`, `nhom_rui_ro`, `ma_lop`, `ma_sv`, `ngay_gui`, `nguoi_gui`, `so_luong_nhan`, `trang_thai`) VALUES ('TB-CHAT-08', 'Thông báo cảnh báo nguy cơ Buộc thôi học', 'Em Kiệt chú ý, tình trạng học tập của em đang ở mức báo động Buộc thôi học. Hãy liên hệ ngay với CVHT trong tuần này.', 'CA_NHAN', 'DCCNTT14B', '20230029', CURRENT_TIMESTAMP, 'TS. Đinh Văn Phong', 1, 'DA_GUI');
INSERT INTO `thong_bao` (`ma_thong_bao`, `tieu_de`, `noi_dung`, `nhom_rui_ro`, `ma_lop`, `ma_sv`, `ngay_gui`, `nguoi_gui`, `so_luong_nhan`, `trang_thai`) VALUES ('TB-CHAT-09', '📬 [SV PHẢN HỒI] Đơn xin xem xét hoàn cảnh gia đình', 'Dạ em chào thầy, đợt vừa rồi gia đình em có biến cố nên em phải nghỉ nhiều buổi. Em mong thầy và nhà trường tạo điều kiện cho em được tiếp tục học tập ạ.', 'PHAN_HOI_SV', 'ALL', '20230029', CURRENT_TIMESTAMP, 'Đỗ Đức Kiệt (20230029)', 1, 'SV_CHUA_DOC');
INSERT INTO `thong_bao` (`ma_thong_bao`, `tieu_de`, `noi_dung`, `nhom_rui_ro`, `ma_lop`, `ma_sv`, `ngay_gui`, `nguoi_gui`, `so_luong_nhan`, `trang_thai`) VALUES ('TB-CHAT-10', 'Tư vấn hướng nghiệp và chuyên ngành Ô tô', 'Chào em, kỳ tới Khoa mở chuyên ngành Chẩn đoán điện Ô tô, em chú ý đăng ký môn tiên quyết nhé.', 'CA_NHAN', 'DCOTO14A', '20230101', CURRENT_TIMESTAMP, 'PGS.TS. Nguyễn Thanh Hải', 1, 'DA_GUI');
INSERT INTO `thong_bao` (`ma_thong_bao`, `tieu_de`, `noi_dung`, `nhom_rui_ro`, `ma_lop`, `ma_sv`, `ngay_gui`, `nguoi_gui`, `so_luong_nhan`, `trang_thai`) VALUES ('TB-CHAT-11', 'Nhắc nhở học tập và đồ án Quản trị kinh doanh', 'Chào em, đồ án môn Quản trị chiến lược hạn nộp là ngày 20/09, nhóm em hoàn thiện sớm nhé.', 'CA_NHAN', 'DCQTKD14A', '20230201', CURRENT_TIMESTAMP, 'ThS. Hoàng Thị Mai', 1, 'DA_GUI');
